/** Password strength calculator */ function getPasswordStrength(password) {
    if (!password) return {
        score: 0,
        label: '',
        color: ''
    };
    let score = 0;
    if (password.length >= 8) score++;
    if (password.length >= 12) score++;
    if (/[A-Z]/.test(password) && /[a-z]/.test(password)) score++;
    if (/\d/.test(password)) score++;
    if (/[^A-Za-z0-9]/.test(password)) score++;
    // Normalize to 0–4
    score = Math.min(4, score);
    const labels = [
        '',
        'Weak',
        'Fair',
        'Good',
        'Strong'
    ];
    const colors = [
        '',
        'oklch(0.6 0.25 15)',
        'oklch(0.75 0.18 55)',
        'oklch(0.85 0.18 90)',
        'oklch(0.72 0.19 155)'
    ];
    return {
        score,
        label: labels[score],
        color: colors[score]
    };
}
/** Email validation */ function isValidEmail(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}
